		["The battered skeleton lies at the edge of the Stonevault trogg camp; {quest:739}, Agmond's killer, walks among the Bonesnappers."] = "破损的骷髅在石窟穴居人营地边缘；杀死埃格蒙德的凶手{quest:739}在石窟断骨者中间巡逻。",
		["The first two cages stand together in the Witherbark village south of {npc:5634}; the third is in the next village to the east. Every Witherbark troll can drop a necklace."] = "前两个笼子一起在{npc:5634}南边的枯木村庄里；第三个在东边的下一个村庄里。每个枯木巨魔都可能掉落项链。",
		["Theramore"] = "塞拉摩岛",
		["Warlock: {quest:3631}"] = "术士：{quest:3631}",
		["Witherbark villages"] = "枯木村庄",
		["{npc:1573}, the {object:32372}"] = "{npc:1573}，{object:32372}",
		["{npc:2616} stands on the docks where the boat lands."] = "{npc:2616}站在船停靠的码头上。",
		["{npc:2817}'s next quest pays no experience: skip it."] = "{npc:2817}的下一个任务不给经验：跳过。",
		["{npc:2888}'s next task is an elite hunt: skip it."] = "{npc:2888}的下一个任务是精英狩猎：跳过。",
		["{npc:5634}'s cocktail needs parts from Kalimdor: skip it."] = "{npc:5634}的鸡尾酒需要卡利姆多的材料：跳过。",
		["{npc:5636}, beside the flight master at the top"] = "{npc:5636}，在顶层飞行管理员旁边",
		["{npc:7884} keeps paying for necklaces: hand in any extras"] = "{npc:7884}会继续收购项链：交上多余的",
} end)()
t.guides["forever/alliance/40-50/03-feralas"] = (function() return {
		["Giants and elementals"] = "巨人和元素",
		["Gordunni ogres"] = "戈杜尼食人魔",
		["Grimtotem camp"] = "恐怖图腾营地",
		["Grimtotem tauren"] = "恐怖图腾牛头人",
		["Grind to 45"] = "刷到45级",
		["Hatecrest naga"] = "憎世纳迦",
		["Hearth to Feathermoon."] = "用炉石返回羽月要塞。",
		["Rage Scar yetis"] = "怒痕雪人",
		["Ride back west along the road, then north into the Rage Scar hills. Every yeti here can drop a hide; one may drop a {quest:7735}, which {npc:7852} pays for too."] = "沿道路向西骑回，然后向北进入怒痕山丘。这里的每个雪人都可能掉落毛皮；可能会掉落{quest:7735}，{npc:7852}也会收购。",
		["Ride east to the Gordunni camp in the hills south-east of the yeti valley: Warlocks and Shaman hold the camp, Brutes wander the slopes around it and further north."] = "向东骑到雪人山谷东南方山丘上的戈杜尼营地：戈杜尼术士和戈杜尼萨满祭司占据着营地，戈杜尼蛮兵在周围和更北边的山坡上游荡。",
		["Ride north into the yeti valley. Every Feral Scar yeti can drop a thick hide; {npc:5346} (level 48) prowls the middle."] = "向北骑进雪人山谷。每个深痕雪人都可能掉落厚毛皮；{npc:5346}（48级）在中间潜行。",
		["Ride north-east to the night elf outpost on the {zone:1441} border."] = "向东北骑到{zone:1441}边境上的暗夜精灵前哨。",
		["Ride west to the friendly mountain giant at the foot of the hills. Land Walkers and Cliff Giants around him are elite: give them room."] = "向西骑到山脚下友好的山岭巨人那里。他周围的{npc:5357}和{npc:5358}是精英：离它们远点。",
		["Ring the bell whenever {npc:7774} stops to wander, and lead her south to {npc:7765}."] = "每当{npc:7774}停下乱走时就摇铃，带她向南到{npc:7765}处。",
		["Shore Striders, Deep Striders and Wave Striders (elite giants) wade along the coast north of the dock: zap one with {item:18904} and kill the shrunken giant. Sea Elementals and Sea Sprays drift in the same surf."] = "{npc:5359}、{npc:5360}和{npc:5361}（精英巨人）在码头北边的海岸涉水：用{item:18904}电一只，然后杀掉缩小的巨人。{npc:5461}和{npc:5462}在同一片浪花中飘荡。",
		["The courier's boat"] = "信使的船",
		["Walk south along the island to the naga ruins; the gazebo stands among them."] = "沿岛向南走到纳迦废墟；索兰萨尔瞭望台在废墟中。",
		["for Tyrande in {zone:1457}: the route takes you there at 47"] = "交给{zone:1457}的泰兰德·语风：路线会在47级带你去那里",
		["if you carry {quest:1100} from {zone:1441}"] = "仅当你带着来自{zone:1441}的{quest:1100}",
		["{item:11463}, from the backpacks"] = "{item:11463}，来自背包",
		["{npc:14637}'s refills are level 55: skip them."] = "{npc:14637}的补充任务是55级：跳过。",
		["{npc:3936}, beside him"] = "{npc:3936}，在他旁边",
		["{npc:7774} wanders the hills north of {npc:7765}, among the Northspring harpies; her bell is in the chest beside her."] = "{npc:7774}在{npc:7765}北边的山丘上、北泉鹰身人之间游荡；她的铃铛在她旁边的箱子里。",
		["{npc:7774}'s escort"] = "护送{npc:7774}",
		["{npc:7877}, at the top of the stronghold"] = "{npc:7877}，在要塞顶层",
		["{npc:8136} waits for the end of the mainland loop."] = "{npc:8136}留到大陆环线结束时。",
} end)()
t.guides["forever/alliance/40-50/04-tanaris"] = (function() return {
		["Follow the coast south to the pirate cove. Southsea pirates crowd the beach and the boats: work along the edge and pull one at a time. {npc:7883} stands on the far side; {npc:7881}'s stolen cargo lies in the camp."] = "沿海岸向南到落帆海湾。南海海盗挤满了海滩和船：沿着边缘清理，一次拉一个。{npc:7883}站在远端；{npc:7881}被偷的货物在营地里。",
		["Gives the {item:8585}"] = "获得{item:8585}",
		["He runs off to keep Rizzle busy"] = "他会跑去拖住Rizzle",
		["Ride east across the dunes to the goblin harbour on the north-east coast."] = "向东骑过沙丘到东北海岸的地精港口热砂港。",
		["Ride north-west to the Centipaar hive in the dunes. Any Centipaar can drop insect parts."] = "向西北骑到沙丘中的森提帕尔虫巢腐化之巢。任何森提帕尔都可能掉落昆虫部件。",
		["Ride south into {quest:3362}. The Dew Collectors drop the glands; only some are full, so keep the Laden one. Gnarled Thistleshrubs and Rootshapers share the valley. The Thistleshrubs are 48-50, above you: pull one at a time."] = "向南骑进{quest:3362}。灌木露水收集者掉落腺体；只有部分是饱满的，留下饱满的露水腺。{npc:5490}和灌木塑根者也在山谷里。灌木怪是48-50级，比你高：一次拉一个。",
		["Ride south-west to the ogre compound. Brutes and Enforcers (46-48) fill it; {npc:12046} (49) stands in the middle with guards around him: clear them first."] = "向西南骑到砂槌营地。里面满是砂槌蛮兵和砂槌执行者（46-48级）；{npc:12046}（49级）站在中间，周围有卫兵：先清理卫兵。",
		["Rizzle's plans"] = "Rizzle的设计图",
		["The Wanted poster beside him"] = "他旁边的通缉布告",
		["Wastewander bandits"] = "废土强盗",
		["While {npc:4709} keeps Rizzle talking, his plans lie unguarded in the gnome camp across the track."] = "{npc:4709}拖住Rizzle说话时，他的设计图就在赛道对面的侏儒营地里，无人看守。",
		["for {zone:1457}: the route takes you there at 47"] = "交给{zone:1457}：路线会在47级带你去那里",
		["{npc:11758}, on the east side of town"] = "{npc:11758}，在镇子东侧",
		["{npc:5955}'s escort"] = "{npc:5955}的护送",
		["{npc:7407}, by the water tower"] = "{npc:7407}，在水塔旁",
		["{npc:7408}, next to him"] = "{npc:7408}，在他旁边",
		["{npc:7583}'s next ingredient grows in the {zone:1425}, and the route never brings it back: skip it."] = "{npc:7583}的下一种材料生长在{zone:1425}，路线不会再回来：跳过。",
		["{npc:7881}, in the port's tavern"] = "{npc:7881}，在港口的酒馆里",
		["{quest:2864}, north side of town"] = "{quest:2864}，镇子北侧",
} end)()
t.guides["forever/alliance/40-50/05-the-hinterlands"] = (function() return {
		["Ashmane Boars and Redstone Basilisks share the slopes south-west of the keep. Keep clear of the Helboars further south: they are level 52."] = "{npc:5992}和{npc:5990}分布在城堡西南方的山坡上。远离更南边的地狱野猪：它们是52级。",
		["Boars and basilisks"] = "野猪和蜥蜴",
		["Hearthstone on cooldown? Ride back north-west."] = "炉石在冷却？向西北骑回去。",
		["Ride back north to Ironband's camp."] = "向北骑回铁环挖掘场的营地。",
		["Ride east along the south shore of the loch to Ironband's camp."] = "沿湖南岸向东骑到铁环挖掘场的营地。",
		["Ride east through {zone:1430} into the {zone:1435} and south down the road into the {zone:1419}. The bloodmages' camp is the first stop beside the road."] = "向东骑过{zone:1430}进入{zone:1435}，再沿道路向南进入{zone:1419}。血法师营地是路旁的第一站。",
		["Ride west: Starving Snickerfangs roam the dry hills just south of the bloodmages' camp; Scorpok Stingers (level 50) scuttle across the middle of the north. {npc:5982} vultures circle over all of it. Pull one at a time."] = "向西骑：{npc:5984}在血法师营地南边的干燥山丘上游荡；{npc:5988}（50级）在北部中间爬行。{npc:5982}秃鹫在整片区域上空盘旋。一次拉一只。",
		["Scorpoks and snickerfangs"] = "厚甲蝎和弯牙土狼",
		["Step through the portal into {zone:1457}. The Temple of the Moon is in the south of the city."] = "穿过传送门进入{zone:1457}。月神殿在城市南部。",
		["Temple of the Moon"] = "月神殿",
		["The bloodmages"] = "血法师",
		["The bloodmages' second tier pays for the same parts with a buff item and no experience: skip it."] = "血法师的第二阶段用增益物品而不是经验来交换同样的材料：跳过。",
		["The druid trainers stand in the Enclave; {zone:1455} has none"] = "德鲁伊训练师站在塞纳里奥区；{zone:1455}没有",
		["the book on her table"] = "她桌上的书",
		["the soil comes from {zone:1449}, later"] = "土壤之后从{zone:1449}获得",
		["{npc:3516}, at the top of the tree"] = "{npc:3516}，在树顶",
		["{npc:7740}, beside her"] = "{npc:7740}，在她旁边",
		["{npc:7744}: the last guide binds here, so this usually ticks at once"] = "{npc:7744}：上一份指南在这里绑定炉石，所以这一步通常会立即完成",
		["{npc:7907}'s next errand goes to {zone:1446}: skip it."] = "{npc:7907}的下一个差事要去{zone:1446}：跳过。",
		["{npc:7916}: keep it, the feathers come at the end of the {zone:1428} guide"] = "{npc:7916}：先留着，羽毛在{zone:1428}指南结尾获得",
		["{quest:2990}, at the top of the keep"] = "{quest:2990}，在城堡顶层",
} end)()
t.guides["forever/alliance/40-50/06-searing-gorge"] = (function() return {
		["For {npc:8256} in {zone:1455}, later"] = "之后交给{zone:1455}的{npc:8256}",
		["Golems and elementals"] = "傀儡和元素",
		["Greater Lava Spiders"] = "{npc:5858}",
		["Heavy War Golems patrol the floor of the Cauldron below Kalaran; Magma Elementals drift among them. Golems and elementals drop the oil, elementals the hearts."] = "{npc:5854}在卡拉然·温布雷下方的大熔炉底部巡逻；{npc:5855}在它们之间飘荡。傀儡和元素掉落油，元素掉落核心。",
		["Taskmasters and Slavers drive the slaves all over the Cauldron, and any of them can carry a {item:10551}. The Steamsmiths work at the furnaces in the middle (the {item:18959}), the Lookouts stand on the southern ridges (the Spyglass). Any {object:147516} may drop the {item:11818}: keep it."] = "黑铁工头和黑铁奴隶贩子在大熔炉各处驱使奴隶，任何一个都可能带着{item:10551}。黑铁锻造师在中间的熔炉旁干活（{item:18959}），黑铁哨兵站在南边的山脊上（侦查员的望远镜）。任何{object:147516}都可能掉落{item:11818}：留着它。",
		["The Grimesilt outhouse"] = "格里塞特厕所",
		["The prisoner's next task, Ledger from {zone:1446}, sends you to the {zone:1435} and {zone:1445}: skip it."] = "囚犯的下一个任务“{zone:1446}的账本”会让你去{zone:1435}和{zone:1445}：跳过。",
		["The spiders roam the plateaus and lava pools in the south-west of the gorge."] = "蜘蛛在峡谷西南部的高地和熔岩池中游荡。",
		["The {object:179827} board"] = "{object:179827}布告板",
		["{npc:6734}: the last guide hearths you here, so this usually ticks at once"] = "{npc:6734}：上一份指南用炉石把你送到这里，所以这一步通常会立即完成",
		["{object:147516} dwarves"] = "{object:147516}矮人",
} end)()
t.guides["forever/alliance/40-50/07-un-goro-crater"] = (function() return {
