		["At 50 {npc:3032}, a shaman trainer in {zone:1456}, sends you to {npc:6176}."] = "50级时，{zone:1456}的萨满祭司训练师{npc:3032}会让你去找{npc:6176}。",
		["Experience and gold"] = "经验和金币",
