t.guides["forever/horde/30-40/02-stranglethorn-vale"] = (function() return {
		["Back north to the camp."] = "向北回到营地。",
		["Back to {object:3202}"] = "返回{object:3202}",
		["Back to {object:3202}."] = "返回{object:3202}。",
		["Basilisks and the Bloodscalp village"] = "蜥蜴和血顶村庄",
		["Bloodscalp headhunters"] = "血顶猎头者",
		["Bloodscalp ruins"] = "血顶废墟",
		["East of the ogres, Shadowmaw Panthers (37-38) stalk unseen until they strike; the Stranglethorn Tigresses roam the same ground and now and then drop a pristine fang. Snapjaw Crocolisks line the river just west of the jungle; keep their skins for {npc:2495}."] = "在食人魔东边，深喉猎豹（37-38级）在攻击前都是隐形的；荆棘谷雌虎在同一片地方游荡，偶尔掉落雌虎的牙齿。钳嘴鳄鱼分布在丛林正西的河边；留着它们的皮交给{npc:2495}。",
		["Elder tigers and Lashtail raptors"] = "老年猛虎和鞭尾迅猛龙",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Follow the road north out of {object:3202}; Nesingwary's hunting camp sits on the hill north-east of the river. From here on, keep every page of {quest:338} you loot: {npc:716} asks for them later."] = "沿道路向北离开{object:3202}；奈辛瓦里的狩猎营地在河东北边的山上。从现在起，留着拾取到的每一页{quest:338}：{npc:716}之后会要。",
		["Follow the road south to {object:3202}."] = "沿道路向南前往{object:3202}。",
		["Green Hills pages"] = "荆棘谷的青山书页",
		["Head west past the camp. Stranglethorn Raptors (33-34) hunt the clearings, and the Bloodscalp trolls hold the ruins on the coast: every Bloodscalp can drop a tusk. A {item:4614} is a very rare drop from them: if one drops, read it."] = "向西经过营地。荆棘谷迅猛龙（33-34级）在林间空地捕猎，血顶巨魔占据着海岸边的废墟：每个血顶巨魔都可能掉落獠牙。他们极少掉落{item:4614}：如果掉了，就阅读它。",
		["Hearth to {object:3202}"] = "用炉石回到{object:3202}",
		["Jungle Stalkers"] = "丛林捕猎者",
		["Lashtail raptors"] = "鞭尾迅猛龙",
		["Leave the {zone:1458} by the lift and walk up through the ruins to the zeppelin towers; the {object:3202} zeppelin is the one on the south-west tower."] = "乘升降梯离开{zone:1458}，穿过废墟走到飞艇塔；前往{object:3202}的飞艇在西南边的塔上。",
		["Mistvale gorillas"] = "迷雾谷猩猩",
		["Mosh'Ogg camp"] = "莫什奥格营地",
		["Nesingwary's camp"] = "奈辛瓦里的营地",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; keep every page you loot and look on the auction house for the rest. {npc:716} takes the chapters later in this guide."] = "{item:2755}的每一页从血顶巨魔和劈颅巨魔身上的掉率约为1%；留着拾取到的每一页，其余的去拍卖行找。{npc:716}会在本指南稍后收取各章节。",
		["Pages of The {item:2755} drop at about 1% each from the Bloodscalp and Skullsplitter trolls; take what drops and check the Auction House for the rest."] = "{item:2755}的每一页从血顶巨魔和劈颅巨魔身上的掉率约为1%；拿上掉落的，其余的去拍卖行找。",
		["Raptors and the Bloodscalp trolls"] = "迅猛龙和血顶巨魔",
		["Ride back south to {object:3202}."] = "向南骑回{object:3202}。",
		["Ride north past Nesingwary's camp to the lake. The Venture Co. Geologists (34-36) work the camps along its western shore; they carry the Tumbled Crystals."] = "向北骑过奈辛瓦里的营地前往湖边。风险投资公司地质学家（34-36级）在湖西岸的营地里干活；他们携带打磨过的水晶。",
		["Shadowmaw jungle and the Snapjaw river"] = "深喉猎豹的丛林和钳嘴鳄鱼的河流",
		["Shadowmaw panthers"] = "深喉猎豹",
		["Stranglethorn Tigers and Panthers (32-33) roam the hills east of the camp, along the lake shore."] = "荆棘谷猛虎和黑豹（32-33级）在营地东边沿湖岸的山丘上游荡。",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202} and train in the city before you fly on."] = "在{object:3202}西侧的塔上乘坐前往{zone:1454}的飞艇，继续飞行前先在城里训练。",
		["The Bloodscalp Headhunters (36-37) in the village on the coast carry the shrunken heads."] = "海岸村庄里的血顶猎头者（36-37级）携带皱缩的头颅。",
		["The Bloodscalp trolls hold the ruins up the coast north of the reef and the village beyond; every one can drop a {item:3915}. Keep looting pages of {quest:338}."] = "血顶巨魔占据着暗礁北边沿海的废墟和更远处的村庄；每个都可能掉落{item:3915}。继续拾取{quest:338}的书页。",
		["The Elder Stranglethorn Tigers (34-35) roam the hills south-west of the camp; the Lashtail Raptors (35-36) hunt further south, towards {object:3202}."] = "老年荆棘谷猛虎（34-35级）在营地西南的山丘上游荡；鞭尾迅猛龙（35-36级）在更南边、靠近{object:3202}的地方捕猎。",
		["The Jungle Stalkers (40-41) hunt the coast south of {object:3202}. They are well above you: pull one at a time and rest between fights."] = "丛林捕猎者（40-41级）在{object:3202}南边的海岸捕猎。它们比你高得多：一次引一只，战斗间隙休息。",
		["The Lashtail Raptors (35-36) hunt the jungle just north-east of {object:3202}."] = "鞭尾迅猛龙（35-36级）在{object:3202}东北不远的丛林里捕猎。",
		["The Mosh'Ogg ogres camp in the hills just east of {object:3202}. Kill one Brute and one Witch Doctor (36-37); pull them one at a time."] = "莫什奥格食人魔在{object:3202}正东的山丘上扎营。杀死一个莫什奥格蛮兵和一个莫什奥格巫医（36-37级）；一次引一个。",
		["The Shadowmaw Panthers (37-38) stalk the jungle east of the Mosh'Ogg hills and north-east towards the lake; they strike from stealth. Loot every Green Hills page you find on the way."] = "深喉猎豹（37-38级）在莫什奥格山丘东边和东北方通往湖泊的丛林里潜行；它们会从潜行中发动攻击。沿途拾取你找到的每一页荆棘谷的青山。",
		["The Shadowmaw Panthers come much later, by {object:3202}"] = "深喉猎豹要很久以后才会遇到，在{object:3202}附近",
		["The camp by the river"] = "河边的营地",
		["The zeppelin lands at the tower on the west side of the camp."] = "飞艇降落在营地西侧的塔上。",
		["Tigers and panthers"] = "猛虎和黑豹",
		["Venture Co. camp"] = "风险投资公司营地",
		["West past the camp, Crystal Spine Basilisks (34-35) sit on the rocks; every Bloodscalp in the village beyond can drop an ear."] = "向西经过营地，晶背蜥蜴（34-35级）趴在岩石上；再往前的村庄里每个血顶巨魔都可能掉落耳朵。",
		["Young Stranglethorn Tigers prowl west of the camp, Young Panthers south and east of it."] = "荆棘谷猛虎幼崽在营地西边游荡，猎豹幼崽在营地南边和东边。",
		["Young tigers and panthers"] = "猛虎幼崽和猎豹幼崽",
		["Zeppelin to {object:3202}"] = "乘飞艇前往{object:3202}",
		["Zeppelin towers"] = "飞艇塔",
		["{npc:2495}: the Snapjaw skins gathered earlier"] = "{npc:2495}：之前收集的钳嘴鳄鱼的皮",
		["{npc:2497}: for Arathi, later on the route"] = "{npc:2497}：交给阿拉希高地，路线后面会去",
		["{npc:5901}: {npc:3527} and your {item:5177}"] = "{npc:5901}：{npc:3527}和你的{item:5177}",
		["{npc:729}, a level 37 tiger, prowls the hilltop south-west of the camp."] = "{npc:729}是一只37级的老虎，在营地西南的山顶上游荡。",
		["{npc:773}'s missing hunters' camp is Nesingwary's: walk among its tents and the investigation completes. River Crocolisks lie along the river below the camp."] = "{npc:773}失踪猎人的营地就是奈辛瓦里的营地：在帐篷间走一圈，调查就会完成。淡水鳄趴在营地下方的河边。",
} end)()
t.guides["forever/horde/30-40/03-arathi-highlands"] = (function() return {
		["Boulderfist camp"] = "石拳营地",
		["Coyotes and buzzards"] = "山狗和秃鹫",
		["Daggerspine shore"] = "刺脊海岸",
		["Escort the professor down to the shore. Two Daggerspine naga ambush him on the way: stay close."] = "护送教授到岸边。途中会有两个刺脊纳迦伏击他：跟紧他。",
		["Fleshstalker raptors"] = "猎兽龙",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Follow the road north; {npc:4618}'s camp is on the way."] = "沿道路向北；{npc:4618}的营地就在路上。",
		["Greater Rock Elementals"] = "巨型石元素",
		["Highland raptors"] = "高地迅猛龙",
		["Into the {zone:1418}"] = "进入{zone:1418}",
		["Lesser Rock Elementals"] = "次级石元素",
		["North-east of Hammerfall the Drywhisker kobolds mine the gorge; the Kobolds at the mouth and the Diggers and Surveyors deeper in all drop the Motes of Myzrael."] = "落锤镇东北方，枯须狗头人在峡谷中采矿；峡谷口的枯须狗头人和深处的枯须掘地工、枯须勘探员都会掉落密斯莱尔之尘。",
		["Ride north; the outer circle stands in the middle of the highlands."] = "向北骑行；外部法阵位于高地中央。",
		["Ride south-west to the goblins' cove on the southern coast. {npc:2766} keeps watch on the cliff above it."] = "向西南骑行到南部海岸的地精海湾。{npc:2766}在海湾上方的悬崖上放哨。",
		["Rock Elementals"] = "石元素",
		["Stonevault troggs"] = "石窟穴居人",
		["Take the {zone:1454} zeppelin from the tower on the west side of {object:3202}."] = "在{object:3202}西侧的塔楼乘飞艇前往{zone:1454}。",
		["The Greater Rock Elementals (42-44, well above you) wander the gulches in the south-west; the bracers drop about one kill in five. Pull one at a time and rest between fights, or leave them. Keep killing coyotes and buzzards you still need on the way."] = "巨型石元素（42-44级，远高于你）在西南部的沟壑中游荡；护腕约五次击杀掉落一次。一次拉一个，战斗间休息，或者放弃。途中继续击杀还需要的山狗和秃鹫。",
		["The Syndicate hold the walled manor and its farm in the north-west; their Highwaymen, Mercenaries and Pathstalkers carry the Bloodstone Amulets."] = "辛迪加占据西北部有围墙的庄园和农场；辛迪加路霸、辛迪加雇佣兵和辛迪加巡路者携带血石护符。",
		["The Witherbark trolls hold the village in the south-eastern hills. Axe Throwers guard the outer huts; the Witch Doctors and Headhunters hold the heart of the village."] = "枯木巨魔占据东南部山丘中的村庄。枯木掷斧者守卫外围的小屋；枯木巫医和枯木猎头者占据村子中心。",
		["The inner circle lies south of the western circle, east of Stromgarde."] = "内部法阵在西部法阵南边、激流堡东边。",
		["The next guide heads into {zone:1445}."] = "下一份指南前往{zone:1445}。",
		["The orc stronghold at the eastern end of the road. {npc:2851}, the wind rider master, stands by the gate."] = "道路东端的兽人要塞。双足飞龙管理员{npc:2851}站在大门旁。",
		["The small elementals drift across the flats just west of {npc:2921}'s camp. Every rock elemental in the zone can drop {npc:6868}'s Rock Elemental Shards: keep them."] = "小型元素在{npc:2921}营地正西的平地上飘荡。这个地区的每个石元素都可能掉落{npc:6868}要的石元素的碎片：留着它们。",
		["The stone's next task needs Fozruk, a level 42 elite: leave it."] = "石头的下一个任务需要击败42级精英弗兹鲁克：放着别管。",
		["The {object:138492}"] = "{object:138492}",
		["The {object:2689}"] = "{object:2689}",
		["The {object:2690}"] = "{object:2690}",
		["The {object:2691}"] = "{object:2691}",
		["The {object:2701} lie at the far end of the gorge."] = "{object:2701}在峡谷最深处。",
		["The {object:2702}"] = "{object:2702}",
		["Train while you are in the {zone:1458}: the trainers stand in the {object:36070}, the {object:36073} and the {object:36082} (Paladins: {npc:260093})."] = "趁在{zone:1458}时训练：训练师在{object:36070}、{object:36073}和{object:36082}（圣骑士：{npc:260093}）。",
		["West of the cove the Daggerspine Raiders and Sorceresses (38-40) hold the shore: pull them one at a time. The two wrecks lie in the shallows off it, the charts and logs inside them; the gems lie on the sea floor around the wrecks."] = "海湾西边，刺脊袭击者和刺脊巫师（38-40级）占据海岸：一次拉一个。两艘沉船在近海浅水中，海图和日志在船里；宝石在沉船周围的海底。",
		["Zeppelin to the {zone:1458}"] = "乘飞艇前往{zone:1458}",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["Zeppelin tower"] = "飞艇塔",
		["for {npc:5395} in {zone:1443}, in the next guide"] = "交给{zone:1443}的{npc:5395}，在下一份指南中",
		["{item:3713}, for \"Swamp Eye\" Jarl in {zone:1445}"] = "{item:3713}，交给{zone:1445}的“沼泽之眼”加尔",
		["{npc:2771}'s next {quest:678} is against Boulderfist elites: leave it."] = "{npc:2771}的下一个{quest:678}要对付石拳精英：放着别管。",
		["{npc:2920}: only if you carry {item:2868} ({skill:164} or the Auction House)"] = "{npc:2920}：仅当你携带{item:2868}时（{skill:164}或拍卖行）",
		["{object:1661} has no Hunter or Shaman trainer: take the {zone:1454} zeppelin from the same tower instead and train in the city, then take the {zone:1458} zeppelin from the tower outside {zone:1454}'s main gate."] = "{object:1661}没有猎人或萨满祭司训练师：改从同一座塔楼乘飞艇前往{zone:1454}，在城里训练，然后从{zone:1454}正门外的塔楼乘飞艇前往{zone:1458}。",
		["{zone:1458} trainers"] = "{zone:1458}的训练师",
} end)()
t.guides["forever/horde/30-40/04-dustwallow-marsh"] = (function() return {
		["Darkfang spiders"] = "暗牙蜘蛛",
		["For {npc:2519} at {object:3202}, in the next guide"] = "交给{object:3202}的{npc:2519}，在下一个指南中",
		["Hearth to Shadowprey"] = "用炉石回到葬影村",
		["Kodo bones and ghosts"] = "科多兽骨和幽灵",
		["Maraudine totems"] = "玛洛迪图腾",
		["Mirefin murlocs"] = "黑鳍鱼人",
		["Pick up the kodo bones scattered across the graveyard, and use the {item:15848} among the bones: the ghosts it draws drop the ghost-o-plasm."] = "捡起散落在坟场各处的科多兽骨，并在骨头间使用{item:15848}：被吸引来的幽灵会掉落幽灵电浆。",
		["Ride back west to Brackenwall with the head."] = "带着头颅向西骑回蕨墙村。",
		["Ride north up the road to the hut by the road north of the graveyard."] = "沿道路向北骑往坟场北边路旁的小屋。",
		["Ride on south-west to Shadowprey."] = "继续向西南骑往葬影村。",
		["Ride west back across the marsh. The Darkfang Venomspitters on the ridges north of Brackenwall drop the venom sacs. Theramore Infiltrators (35-36) sneak through the same woods: they are stealthed, so look closely."] = "向西骑回沼泽对面。蕨墙村北边山脊上的暗牙毒蜘蛛掉落毒囊。塞拉摩间谍（35-36级）潜伏在同一片树林里：他们处于潜行状态，所以要仔细看。",
		["Slitherblade coast"] = "滑刃海岸",
		["Stinky Ignatz"] = "伊格纳兹",
		["Swamp Eye Jarl"] = "“沼泽之眼”加尔",
		["Take the road north at the fork to the ogre village of Brackenwall."] = "在岔路口沿道路向北，前往食人魔村庄蕨墙村。",
		["The Darkmist spiders swarm the cavern mouth north-west of Brackenwall; every kind drops eyes."] = "黑雾蜘蛛聚集在蕨墙村西北的洞口；每种都会掉落眼球。",
		["The next guide takes you back to {zone:1434}."] = "下一个指南会带你回到{zone:1434}。",
		["only if you carry a {item:3853} ({skill:164} or the Auction House)"] = "仅当你带着{item:3853}时（{skill:164}或拍卖行）",
		["{npc:4503}, at the south edge of the village where the road comes in"] = "{npc:4503}，在道路进入村庄处的南缘",
		["{npc:5395} and {npc:5412} stand in the post just west of {npc:11596}'s camp."] = "{npc:5395}和{npc:5412}站在{npc:11596}营地正西的哨站里。",
		["{npc:6791}: the last guide binds here, so this usually ticks at once"] = "{npc:6791}：上一份指南在这里绑定炉石，所以这一步通常会立即完成",
		["{object:20985}, beside the manor"] = "{object:20985}，在庄园旁边",
		["{object:20985}, now that {npc:4791} has read the report"] = "{object:20985}，现在{npc:4791}已经读过报告了",
} end)()
t.guides["forever/horde/40-50/01-stranglethorn-vale"] = (function() return {
		["Draenethyst crystals"] = "德莱尼水晶",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Follow the coast south. The naga explorers wade along the shore and carry the reed bundles; the {object:759} bubbles in the hills just east of them."] = "沿海岸向南。纳迦探险者在岸边涉水而行，携带一捆海蛇草；{object:759}就在他们正东的山丘里冒泡。",
		["Further north, the goblins of the Venture Co. dig at the mine east of the road; miners, foremen, surveyors and tinkerers all drop the crystals."] = "再往北，风险投资公司的地精在道路东边的矿洞里挖掘；矿工、工头、勘探员和修理工都会掉落水晶。",
		["Hand Unbagwa the fangs and stay by him: he calls three waves of gorillas, then {npc:1514}. Fight them one at a time."] = "把猩猩牙交给安巴格瓦并待在他身边：他会召唤三波猩猩，然后是{npc:1514}。一次对付一个。",
		["Hearth to {object:3202}"] = "用炉石回到{object:3202}",
		["Into the {zone:1435}"] = "进入{zone:1435}",
		["Jungle stalkers"] = "丛林捕猎者",
		["Mistvale gorillas"] = "迷雾谷猩猩",
		["Naga shore and the {object:759}"] = "纳迦海岸和{object:759}",
		["North-east of Mistvale, Zanzil's followers camp in the jungle; every one of them can carry the mixture."] = "在迷雾谷东北，赞吉尔的追随者在丛林里扎营；他们每个人都可能携带赞吉尔的药剂。",
		["Pirate ghosts"] = "海盗幽灵",
		["Ride north to the Skullsplitter ruins east of the Venture Co. mine; pull the headhunters and berserkers one at a time. {npc:1059} guards the south-western ruins, and one pile of trophy skulls stands on the ruins' north side. Every Skullsplitter can drop a tusk or a necklace: the necklaces are the slow part, so keep killing in the warriors' camp north of the ruins until you have them all."] = "向北骑往风险投资公司矿洞东边的劈颅巨魔废墟；把猎头者和狂战士一个个引出来。{npc:1059}守卫着西南边的废墟，一堆颅骨堆就在废墟北侧。每个劈颅巨魔都可能掉落獠牙或项链：项链是最慢的部分，所以在废墟北边的战士营地里一直杀，直到拿齐为止。",
		["Ride north up the road to the hunters' camp."] = "沿道路向北骑往猎人营地。",
		["Ride north up the road; the hunters camp on the hill above the river."] = "沿道路向北骑行；猎人们在河上方的山丘上扎营。",
		["Ride north-west to {object:3202}."] = "向西北骑往{object:3202}。",
		["Ride west to {object:3202}."] = "向西骑往{object:3202}。",
		["Sawtooth crocolisks"] = "盐齿鳄鱼",
		["Sawtooth snappers"] = "盐齿钳嘴鳄",
		["Skullsplitter warriors"] = "劈颅战士",
		["The Bloodsail ships"] = "血帆海盗船",
		["The gorillas roam the valley around Unbagwa. The elders drop the giblets; any of them can drop a fang."] = "猩猩在安巴格瓦周围的山谷里游荡。老迈的猩猩掉落内脏；任何猩猩都可能掉落猩猩牙。",
		["The last skulls are in the ruins a short ride west, on the way back to {object:3202}."] = "最后的颅骨堆在西边不远的废墟里，就在回{object:3202}的路上。",
		["The next guide starts here and takes you to {zone:1446}."] = "下一个指南从这里开始，带你前往{zone:1446}。",
		["The next trophy skulls stand in the small ruins just north of the warriors' camp."] = "下一堆颅骨堆在战士营地正北的小废墟里。",
		["The snappers line the strand south of the post."] = "钳嘴鳄分布在哨站南边的海滩上。",
		["The stalker raptors hunt the jungle south of {object:3202}, out towards the west coast."] = "丛林捕猎者迅猛龙在{object:3202}南边的丛林里捕猎，一直到西海岸。",
		["Venture Co. mine"] = "风险投资公司矿洞",
		["West of the expedition, the Bloodscalp chiefs {npc:1061} and {npc:1062} stand together in the ruins of Zul'Kunda. Clear their guards first, then pull them."] = "在远征队营地西边，血顶酋长{npc:1061}和{npc:1062}一起站在祖昆达废墟里。先清掉他们的守卫，再引他们。",
		["Zanzil's camps"] = "赞吉尔的营地",
		["Zul'Kunda"] = "祖昆达废墟",
		["Zul'Mamwe"] = "祖玛维废墟",
		["for Stoley in {zone:1446}"] = "交给{zone:1446}的斯杜雷",
		["for a later stop in the {zone:1435}"] = "留到之后在{zone:1435}停留时",
		["for later: the {zone:1425}, around level 48"] = "留到之后：{zone:1425}，大约48级时",
		["the {object:2076}"] = "{object:2076}",
		["the {object:2076}, beside {npc:2497}"] = "{object:2076}，在{npc:2497}旁边",
} end)()
t.guides["forever/horde/40-50/02-feralas"] = (function() return {
		["Eastern Wastewander camps"] = "东部废土营地",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Grimtotem camp"] = "恐怖图腾营地",
		["Keep riding west to the coast. The Coast Crawl Deepseers and Snapclaws on the beaches drop OOX-22/FE's distress beacon about one kill in forty: if one drops, use it to start the quest."] = "继续向西骑到海岸。海滩上的海滩龙虾人先知和海滩利爪龙虾人大约每杀四十只掉落一个OOX-22/FE定位器：如果掉了，就使用它开始任务。",
		["North of the gnolls the ogres hold a hilltop outpost; pull the ogre-magi to you. The cobalt is in the dirt mounds around the outpost, and the scroll lies on the ground inside it."] = "在豺狼人北边，食人魔占据着一座山顶前哨站；把食人魔法师引到你身边来打。戈杜尼钴矿石在前哨站周围的土堆里，戈杜尼卷轴就在前哨站里的地上。",
		["Ride north-east to the goblin harbour on the coast."] = "向东北骑往海岸边的地精港口。",
		["Ride west into the middle of {zone:1444}. Kill a {npc:5308}, use {item:10699} on its body and kill the spirit that rises."] = "向西骑进{zone:1444}中部。杀死一只{npc:5308}，对它的尸体使用{item:10699}，再杀死升起的灵魂。",
		["Riding at 40"] = "40级学骑术",
		["Riding needs level 40 and costs 100 gold; learning it gives you a mount. {npc:4752} teaches Orcs in the {object:172958}, by {npc:3362}'s kennel; no Skyborne riding trainer is known, so Skyborne try {npc:4752} too. Your race's other mounts are 20 gold each: Collectibles, Mounts · Level 40 has a guide for each."] = "骑术需要40级，花费100金；学会后会获得一匹坐骑。{npc:4752}在{object:172958}教授兽人，就在{npc:3362}的狼舍旁；目前不知道天裔的骑术训练师，所以天裔也试试找{npc:4752}。你种族的其他坐骑每匹20金：收藏指南“坐骑 · 40级”为每种坐骑都提供了指南。",
		["Rogue Vale screechers"] = "游荡的山谷尖啸者",
		["South along the coast, the Southsea pirates hold the cove. {npc:7883} and the stolen cargo are on the docks at its far end. Any pirate can drop a hat, the kidnappers most often."] = "沿海岸向南，南海海盗占据着海湾。{npc:7883}和被偷的货物在海湾尽头的码头上。任何海盗都可能掉落海盗帽，南海绑匪掉得最多。",
		["Southern Gordunni ruins"] = "南部戈杜尼废墟",
		["Southern Wastewander camps"] = "南部废土营地",
		["Sprite darters and Woodpaw alphas"] = "小精龙和木爪突击队员",
		["The Grimtotem tauren camp beside the sprite darters' grove; raiders, naturalists and shamans all carry horns."] = "恐怖图腾牛头人在小精龙的树林旁扎营；恐怖图腾袭击者、恐怖图腾博学者和恐怖图腾萨满祭司都携带恐怖图腾之角。",
		["The Woodpaw gnolls camp in the hills just north-west of Mojache; any of them can drop a mane."] = "木爪豺狼人在莫沙彻营地西北不远的山丘上扎营；任何一个都可能掉落鬃毛。",
		["The Zukk'ash hive burrows into the hills south-east of the camp; {quest:7731} waits in its deepest chamber."] = "祖卡什异种蝎的巢穴深入营地东南的山丘；{quest:7731}在最深处的洞室里等候。",
		["The battle map lies in the Woodpaw camp south of Mojache."] = "木爪作战地图在莫沙彻营地南边的木爪营地里。",
		["The sprite darters flit over the grove just west of Mojache; nearly every one drops a wing. The Woodpaw alphas lead the camps south-west of it: kill them within the hour."] = "小精龙在莫沙彻营地正西的树林上空飞来飞去；几乎每只都会掉落翅膀。木爪突击队员率领着树林西南的营地：在一小时内杀死它们。",
		["The {object:3202} zeppelin leaves from the tower just north-east of {zone:1454}'s main gate."] = "前往{object:3202}的飞艇从{zone:1454}正门东北不远的塔上出发。",
		["The {zone:1454} zeppelin leaves from the tower beside {object:3202}; it lands just outside {zone:1454}'s main gate."] = "前往{zone:1454}的飞艇从{object:3202}旁的塔上出发；它降落在{zone:1454}正门外。",
		["Wolves: {npc:3362}, beside {npc:4752}."] = "狼：{npc:3362}，在{npc:4752}旁边。",
		["Woodpaw battle map"] = "木爪作战地图",
		["Woodpaw north camp"] = "木爪北营地",
		["Zeppelin to {object:3202}"] = "乘飞艇前往{object:3202}",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["Zeppelin tower"] = "飞艇塔",
		["for the {zone:1425}, around level 48"] = "交给{zone:1425}，大约48级时",
		["for {zone:1454}, around level 45"] = "交给{zone:1454}，大约45级时",
		["the {object:150075} in the square"] = "广场上的{object:150075}",
		["water pouches in your bags"] = "背包里的废土水袋",
		["{npc:3690}, riding trainer"] = "{npc:3690}，骑术训练师",
		["{npc:4752}, riding trainer"] = "{npc:4752}，骑术训练师",
		["{npc:4773}, riding trainer"] = "{npc:4773}，骑术训练师",
		["{npc:7953}, riding trainer"] = "{npc:7953}，骑术训练师",
		["{npc:8115}: for {zone:1454}, around level 45"] = "{npc:8115}：交给{zone:1454}，大约45级时",
		["{npc:8579}: the screechers live in {zone:1444}"] = "{npc:8579}：尖啸者生活在{zone:1444}",
		["{quest:2863}: one hour from now"] = "{quest:2863}：从现在起一小时内",
} end)()
t.guides["forever/horde/40-50/03-feralas"] = (function() return {
		["Dragon caves"] = "龙穴",
		["Fly to {object:3202}"] = "飞往{object:3202}",
		["Forest walkers"] = "森林漫游者",
		["Frayfeather hippogryphs"] = "乱羽角鹰兽",
		["Monstrous Crawlers"] = "巨型淤泥蟹",
		["Murlocs of the Misty Reed"] = "芦苇丛中的鱼人",
		["North-west along the road, the Rage Scar yetis live around the caves in the hills. Any of them can also drop a {quest:7738}, which starts a quest of its own."] = "沿道路向西北，狂暴的怒痕雪人住在山丘里的洞穴周围。它们也都可能掉落{quest:7738}，它可以开始一个单独的任务。",
		["Northspring harpies"] = "北泉鹰身人",
		["Onyxia's eggs"] = "奥妮克希亚的蛋",
		["Rage Scar yetis"] = "怒痕雪人",
		["Ride back north to Brackenwall."] = "向北骑回蕨墙村。",
		["Ride west along the road; the scroll lies at the water's edge in the swamp's far west."] = "沿道路向西骑行；卷轴在沼泽最西边的水边。",
		["Sea elementals and sea sprays wash along the shore around the dock. Zap the giants with {item:18904} first: shrunken, they lose their elite strength. Shore striders wade in the water; the land walkers and cliff giants roam the hills further north."] = "海元素和巨型海元素沿着码头周围的海岸漂荡。先用{item:18904}电击巨人：被缩小后，它们就失去了精英的力量。海岸巨人在水中涉行；大地行者和峭壁巨人在更北边的山丘上游荡。",
		["South of the vale the Frayfeather hippogryphs roost on the slopes; nearly every one drops sinew and metallic fragments."] = "在山谷南边，乱羽角鹰兽栖息在山坡上；几乎每只都会掉落肌腱和金属碎片。",
		["Sprite darters and forest walkers"] = "小精龙和森林漫游者",
		["The Marsh Murlocs live on the strand south of the post; the Inkspewers are along the shore east of it and the Flesheaters further west, around the huts on the western shore."] = "沼泽鱼人住在哨站南边的海滩上；沼泽喷墨鱼人在哨站东边的岸边，沼泽食腐鱼人在更西边、西岸的小屋周围。",
		["The Monstrous Crawlers walk the beaches of the east coast, few and far between: kill every one you see on the way south."] = "巨型淤泥蟹在东海岸的海滩上走动，数量稀少、相隔很远：向南的路上见一只杀一只。",
		["The Northspring harpies nest on the ridges in the far north-west. They are 48-50, a few levels above you: the Windcallers heal, so kill them first and pull one at a time."] = "北泉鹰身人在遥远西北的山脊上筑巢。它们是48-50级，比你高几级：北泉唤风者会治疗，所以先杀它们，一次引一只。",
		["The same murlocs again, plus the Oracles, who stay near the huts on the western shore."] = "还是同样的鱼人，外加沼泽鱼人智者，它们待在西岸的小屋附近。",
		["The small Horde post on the southern shore."] = "南岸的部落小哨站。",
		["The sprite darters flit over the grove just west of the camp and carry the {item:9589}; the Wandering Forest Walkers, a little further west, carry the Splintered Logs."] = "小精龙在营地正西的树林上空飞来飞去，携带{item:9589}；再往西一点的森林漫游者携带断裂的原木。",
		["The zeppelin to {zone:1454} leaves from the tower beside {object:3202}; it lands just north-east of {zone:1454}'s main gate."] = "前往{zone:1454}的飞艇从{object:3202}旁的塔上出发；它降落在{zone:1454}正门东北不远处。",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["Zeppelin tower"] = "飞艇塔",
		["for the {npc:5598} in the {zone:1425}, around level 48"] = "交给{zone:1425}的{npc:5598}，大约48级时",
		["for the {object:2555} in {zone:1445}, later in this guide"] = "交给{zone:1445}的{object:2555}，在本指南稍后",
		["for the {zone:1425} owlbeasts, around level 48"] = "交给{zone:1425}的枭兽任务，大约48级时",
		["the {object:2555}"] = "{object:2555}",
		["{npc:4500} is elite: grouping up is advised. Beat him down until he gives up, then report to {npc:4501}."] = "{npc:4500}是精英：建议组队。把他打到认输，然后向{npc:4501}报告。",
		["{npc:7875}: for {npc:7010} in {zone:1454}, around level 50"] = "{npc:7875}：交给{zone:1454}的{npc:7010}，大约50级时",
		["{object:172958}, then the {object:172960} and the {object:172961}."] = "{object:172958}，然后是{object:172960}和{object:172961}。",
		["{quest:7738}, a rare drop"] = "{quest:7738}，稀有掉落",
} end)()
t.guides["forever/horde/40-50/04-tanaris"] = (function() return {
		["Dark Iron Lookouts"] = "黑铁哨兵",
		["Further south, Junior Surveyor Scrimshank's gear lies at the mouth of a Centipaar hive."] = "再往南，初级勘察员谢申克的勘探设备在一个森提帕尔巢穴的入口处。",
		["Greater Lava Spiders"] = "灼热熔岩蜘蛛",
		["Heavy War Golems patrol the Cauldron below Kalaran and drop the oil; the Magma and Blazing Elementals drifting among them drop the hearts. The Dark Iron Taskmasters and Slavers drive the slaves on the paths; a Slaver may drop the {item:11818}: keep it."] = "重型作战傀儡在卡拉然下方的大熔炉里巡逻，掉落傀儡之油；在它们中间漂荡的熔岩元素和炽热元素掉落烈焰之心。黑铁工头和黑铁奴隶贩子在小路上驱赶奴隶；黑铁奴隶贩子可能掉落{item:11818}：留着它。",
		["His next request needs the {item:10552} from elite cultists: leave it."] = "他的下一个请求需要精英信徒身上的{item:10552}：别接。",
		["OOX-17/TN"] = "OOX-17/TN",
		["Only with the {item:11818}: back east to the {object:173265} at the dig site."] = "仅当你有{item:11818}时：向东回到挖掘场的{object:173265}。",
		["Scrimshank's gear"] = "谢申克的勘探设备",
		["South down the road again."] = "再次沿道路向南。",
		["South-east of Gadgetzan the Wastewander bandits camp in the dunes; {npc:7847} stands in the eastern camp."] = "在加基森东南，废土强盗在沙丘里扎营；{npc:7847}站在东边的营地里。",
		["The Dark Iron Lookouts stand on the ridges around the sentry towers south of the Cauldron; about one in ten carries the {item:18960}."] = "黑铁哨兵站在大熔炉南边哨塔周围的山脊上；大约十分之一带着{item:18960}。",
		["The Dark Iron Steamsmiths work the furnaces in the middle of the Cauldron; half of them carry a {item:10551}, one in ten the {item:18959}. Slaves, Slavers and Taskmasters carry daggers too."] = "黑铁锻造师在大熔炉中央的熔炉旁干活；他们一半带着{item:10551}，十分之一带着{item:18959}。奴隶工、黑铁奴隶贩子和黑铁工头也带着匕首。",
		["The Greater Lava Spiders roam the plateaus and lava pools in the south-west of the gorge."] = "灼热熔岩蜘蛛在峡谷西南的高地和熔岩池一带游荡。",
		["The Steamsmiths' furnaces"] = "黑铁锻造师的熔炉",
		["The {object:179827} board"] = "{object:179827}告示板",
		["West of Gadgetzan, use the {item:8584} beside the water hole in the troll camp."] = "在加基森西边，在巨魔营地的水坑旁使用{item:8584}。",
		["West of the compound the cactus creatures fill the valley; only the Dew Collectors carry a dew gland. Most mobs in {zone:1446} can drop OOX-17/TN's distress beacon, rarely: keep it if you see one."] = "在营地西边，仙人掌生物占满了山谷；只有灌木露水收集者携带露水腺。{zone:1446}的大多数怪物都可能掉落OOX-17/TN定位器，但很少见：如果看到就留着。",
		["West, the Centipaar insects swarm around their hives; any of them drops the parts."] = "向西，森提帕尔虫群聚集在它们的巢穴周围；任何一只都会掉落森提帕尔昆虫肢体。",
		["the {item:8526} grows in the {zone:1425}, around level 48"] = "{item:8526}生长在{zone:1425}，大约48级时",
		["the {object:150075} in the square"] = "广场上的{object:150075}",
		["the {object:173265}"] = "{object:173265}",
		["{item:11818}, a rare drop"] = "{item:11818}，稀有掉落",
		["{item:8623}, a rare drop"] = "{item:8623}，稀有掉落",
		["{npc:5955}'s escort"] = "护送{npc:5955}",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在双足飞龙管理员旁边",
} end)()
t.guides["forever/horde/40-50/05-the-hinterlands"] = (function() return {
		["East of the road the Ashmane boars and Grunters root on the slopes beside the Redstone basilisks. Stay away from the level 52 Helboars further south."] = "在道路东边，灰鬃野猪和格朗特在红石蜥蜴旁的山坡上拱土。远离更南边52级的地狱野猪。",
		["East of the village, the violet flower grows in the hills."] = "在村庄东边，紫色水生菇生长在山丘上。",
		["Follow the roads east across the {zone:1425} to the troll village on the eastern coast."] = "沿道路向东穿过{zone:1425}，前往东海岸的巨魔村庄。",
		["Grind to 48"] = "刷到48级",
		["Highvale"] = "高原精灵",
		["North along the coast, {npc:14731}'s picnic basket is on the small island; a {npc:14748} guards it."] = "沿海岸向北，{npc:14731}的午餐篮在小岛上；一个{npc:14748}守着它。",
		["OOX-09/HL"] = "OOX-09/HL",
		["Only if you are not level 48 yet."] = "仅当你还没到48级时。",
		["Ride back north to the bloodmages."] = "向北骑回血法师那里。",
		["Saltwater Snapjaws"] = "海水钳嘴龟",
		["Silvermane Howlers"] = "银鬃嗥狼",
		["South of the lodge the Witherbark trolls hold their villages. Every one of them carries a skull: with twenty, use {item:15002} to make the Laden Pike, then plant it inside the village."] = "在旅舍南边，枯木巨魔占据着他们的村庄。他们每个都携带头皮：收集到二十个后，使用{item:15002}做成尼姆布亚的长矛，然后把它插在村子里。",
		["South-west, the Silvermane Howlers roam the hills east of the Witherbark villages."] = "在西南，银鬃嗥狼在枯木村庄东边的山丘上游荡。",
		["The Vilebranch temples"] = "邪枝神殿",
		["The big turtles crawl along the beaches north of the village. {npc:2491}'s port bottles lie on these beaches too, but his quest is not on this route. A snapjaw can drop OOX-09/HL's distress beacon, rarely: keep it."] = "大海龟沿着村庄北边的海滩爬行。{npc:2491}的酒瓶也在这些海滩上，但他的任务不在本路线上。钳嘴龟可能掉落OOX-09/HL定位器，但很少见：留着它。",
		["The bloodmages"] = "血法师",
		["The central hills"] = "中部山丘",
		["The eastern slopes"] = "东部山坡",
		["The five quests share the same parts: gather them all in one sweep. West of the road the {npc:5982} vultures, Starving Snickerfangs, Scorpok Stingers and Deatheye basilisks share the hills."] = "这五个任务需要的是同样的部件：一趟全部收集齐。在道路西边，{npc:5982}秃鹫、饥饿的弯牙土狼、厚甲毒刺蝎和死眼蜥蜴共处于山丘上。",
		["The northern beasts"] = "北部的野兽",
		["Their follow-ups ask for the same parts again for a buff item and pay no experience: leave them."] = "他们的后续任务又要同样的部件，换取一件增益物品，而且不给经验：别接。",
		["Vilebranch soothsayers"] = "邪枝占卜者",
		["Vulture hills"] = "秃鹫山丘",
		["for {npc:6986} in {zone:1454}, around level 50"] = "交给{zone:1454}的{npc:6986}，大约50级时",
		["for {npc:7825} in the {zone:1458}, around level 50"] = "交给{zone:1458}的{npc:7825}，大约50级时",
		["grind on {npc:5982} at the northern hills, {zone:1419}"] = "在{zone:1419}北部山丘刷{npc:5982}",
		["{item:8704}, a rare drop"] = "{item:8704}，稀有掉落",
		["{npc:14731}'s lunch"] = "{npc:14731}的午餐",
		["{npc:6741}: for {zone:1456}, around level 50"] = "{npc:6741}：交给{zone:1456}，大约50级时",
		["{npc:7801}'s camp"] = "{npc:7801}的营地",
		["{npc:7825}, the {object:36126}"] = "{npc:7825}，在{object:36126}",
} end)()
t.guides["forever/horde/40-50/06-azshara"] = (function() return {
		["Back north-east to {npc:8420}."] = "向东北回到{npc:8420}那里。",
		["Back to {object:3202}"] = "返回{object:3202}",
		["Follow the road south; the basilisks bask on the rocks east of it in the middle of the jungle. Their shards drop often."] = "沿道路向南；蜥蜴在丛林中部道路东边的岩石上晒太阳。它们经常掉落碎片。",
		["Frayfeather Hippogryphs"] = "乱羽角鹰兽",
		["Highborne and Haldarr satyrs"] = "上层精灵和哈达尔萨特",
		["Ironjaw Basilisks"] = "铁腭蜥蜴",
		["Keep the deliveries for {npc:4046}, {npc:8659} and {npc:6522}: you pass {zone:1456}, {zone:1454} and the {zone:1458} later."] = "留着给{npc:4046}、{npc:8659}和{npc:6522}的货物：你之后会经过{zone:1456}、{zone:1454}和{zone:1458}。",
		["Keep {quest:3444}: {npc:7771}'s chest is opened on a later visit."] = "留着{quest:3444}：{npc:7771}的箱子要之后再来时才能打开。",
		["Only once all three robots are home"] = "仅当三个机器人都回家后",
		["Ride into {zone:1447}"] = "骑马进入{zone:1447}",
		["Ride south-west to the ruins. The four tablets lie among the ruins, guarded by Spitelash naga; any Siren or Myrmidon can carry {npc:8420}'s rune."] = "向西南骑往废墟。四块石板散落在废墟中，由恶鞭纳迦看守；任何恶鞭海妖或恶鞭侍从都可能携带{npc:8420}的符文。",
		["Sea elementals"] = "海元素",
		["Sprite Darters"] = "小精龙",
		["Take the zeppelin back to {zone:1454}."] = "乘飞艇返回{zone:1454}。",
		["The Highborne ghosts haunt the ruins just north of the shrine; the Haldarr satyrs camp a little further north."] = "上层精灵的幽灵在神殿正北的废墟里出没；哈达尔萨特在更北一点的地方扎营。",
		["The Land Walkers and Cliff Giants roam the hills north of the dock. Zap each one with {item:18904} first: shrunken, they are no longer elite. Every zapped giant drops residue; use the Muisek Vessel on its body too."] = "大地行者和峭壁巨人在码头北边的山丘上游荡。先用{item:18904}电击每一个：被缩小后，它们就不再是精英。每个被电击的巨人都会掉落残渣；也对它的尸体使用灵魂精华容器。",
		["The Sea Elementals and Sea Sprays wash along the shore around the dock."] = "海元素和巨型海元素沿着码头周围的海岸漂荡。",
		["The blood elves' camp lies just south of {npc:8420}. His four pieces of equipment lie in the crates around the camp."] = "血精灵的营地就在{npc:8420}南边。他的四件设备在营地周围的箱子里。",
		["The faerie dragons flit around the woods just west of the camp. Use the vessel on each one you kill."] = "精灵龙在营地正西的树林里飞来飞去。对你杀死的每一只使用容器。",
		["The hippogryphs nest on the hills south-west of the camp. Kill one, then use the Muisek Vessel on its body."] = "角鹰兽在营地西南的山丘上筑巢。杀死一只，然后对它的尸体使用灵魂精华容器。",
		["The treants wander the forest roads between the camp and the middle of {zone:1444}; there are only a few, so look along the paths."] = "树人在营地和{zone:1444}中部之间的林间道路上游荡；数量很少，所以沿着小路找。",
		["The {object:2076} beside {npc:2519}"] = "{npc:2519}旁边的{object:2076}",
		["To {object:3202}"] = "前往{object:3202}",
		["Undamaged Hippogryph Feathers"] = "完好无损的角鹰兽羽毛",
		["Wandering Forest Walkers"] = "森林漫游者",
		["Zapped giants"] = "被电击的巨人",
		["Zeppelin to {zone:1454}"] = "乘飞艇前往{zone:1454}",
		["{npc:6986}, the Drag"] = "{npc:6986}，在暗巷区",
		["{npc:7776}: the bears are in {zone:1448}"] = "{npc:7776}：熊在{zone:1448}",
		["{npc:7825} stands in the {object:36082}."] = "{npc:7825}站在{object:36082}。",
		["{npc:7876}'s tar and Pestlezugg's samples come from {zone:1449}."] = "{npc:7876}要的焦油和匹斯特苏格要的样本都来自{zone:1449}。",
		["{npc:7876}, beside the wind rider master"] = "{npc:7876}，在双足飞龙管理员旁边",
		["{npc:8395}, at the east edge of the camp: no experience, only a teleport to Azshara Tower"] = "{npc:8395}，在营地东缘：没有经验，只能传送到克希雷姆的法师塔",
		["{npc:8659}, the {object:172960}"] = "{npc:8659}，在{object:172960}",
		["{quest:3761} is gathered in the next guide; {npc:4046}'s payment goes back to {npc:8587} later."] = "{quest:3761}在下一个指南中收集；{npc:4046}的报酬之后交还给{npc:8587}。",
} end)()
t.guides["forever/horde/50-60/01-un-goro-crater"] = (function() return {
		["Black Broodlings"] = "黑色小龙",
		["Bloodpetal Flayers"] = "血瓣花掠夺者",
		["Cross the south of the crater to the pylon on the western cliffs."] = "穿过环形山南部，前往西边悬崖上的水晶塔。",
		["Darrowshire Spirits"] = "达隆郡居民的灵魂",
		["Eastern Pylon"] = "东部水晶塔",
		["Escort {npc:9999}"] = "护送{npc:9999}",
		["Follow the cliffs south to {quest:3821}, the Firegut ogres' hill. {npc:9136}'s remains lie at its foot."] = "沿悬崖向南前往火腹食人魔的山丘{quest:3821}。{npc:9136}的遗骸在山脚下。",
		["Free Darrowshire Spirits: talk to them"] = "释放达隆郡居民的灵魂：和它们交谈",
		["From here on pick up every Power Crystal (blue, green, red, yellow) and every {quest:3761} pile you pass: 25 soil in all, 20 for Hamuul and 5 for Pestlezugg."] = "从现在起，捡起路过的每一块能量水晶（蓝色、绿色、红色、黄色）和每一堆{quest:3761}：总共25份土壤，20份给哈缪尔，5份给匹斯特苏格。",
		["Gorillas"] = "猩猩",
		["Into the {zone:1427}"] = "进入{zone:1427}",
		["Into {zone:1449}"] = "进入{zone:1449}",
		["Keep the bait: {npc:9684} is level 56, and the second loop passes his lair."] = "留着诱饵：{npc:9684}是56级，第二圈会经过它的巢穴。",
		["Keep {npc:9118}'s {quest:4147} and {npc:8737}'s letter for later guides."] = "留着{npc:9118}的{quest:4147}和{npc:8737}的信，在之后的指南中使用。",
		["Lar'korwi Mates"] = "拉克维的配偶",
		["Lashers and Threshers"] = "鞭笞者和猛击者",
		["North of Torwa, a dead Threshadon lies by the water."] = "在托尔瓦北边，一头死去的蛇颈龙躺在水边。",
		["Northern Pylon"] = "北部水晶塔",
		["Out of the refuge"] = "离开避难所",
		["Pestlezugg's next quest needs the {npc:10041}, an elite boss. Skip it."] = "匹斯特苏格的下一个任务需要击败精英首领{npc:10041}。跳过它。",
		["Power Crystals and soil"] = "能量水晶和土壤",
		["Ride down the east side of the crater to the pylon on the eastern cliffs."] = "沿环形山东侧骑下去，前往东边悬崖上的水晶塔。",
		["Ride north along the east side. Bloodpetal Lashers and Threshers fill the jungle."] = "沿东侧向北骑行。血瓣花鞭笞者和血瓣花猛击者占满了丛林。",
		["Ride south-west along the western cliffs. {npc:9167} fly over the west side, and Bloodpetal Trappers grow in the same jungle."] = "沿西边的悬崖向西南骑行。{npc:9167}在西侧上空飞翔，血瓣花捕兽者生长在同一片丛林里。",
		["Ride west to the dig site. {npc:7039} golems (53) stomp around it and drop the shards often; the {quest:4296} stands in its middle among the Thaurissan dwarves. Copy it."] = "向西骑往挖掘场。{npc:7039}傀儡（53级）在周围走动，经常掉落碎片；{quest:4296}立在挖掘场中央的索瑞森矮人中间。抄录它。",
		["South of the hot springs, Stegodons graze and Dinosaur Bones drop from them or lie on the ground; Diemetradons nearby carry the scales {npc:9998} wants. Ravasaurs hunt in packs in the south-west: their claws are for {npc:8659}, and now and then one carries a Mangled Journal (a rare drop: take its quest only if you get one). Avoid Gruff, a level 57 Stegodon."] = "在温泉南边，剑龙在吃草，恐龙骨头从它们身上掉落或散落在地上；附近的双帆龙携带{npc:9998}想要的鳞片。暴掠龙在西南成群捕猎：它们的爪子是给{npc:8659}的，偶尔会有一只携带被撕破的日记（稀有掉落：只有拿到了才接它的任务）。避开57级的剑龙格鲁夫。",
		["Stegodons and ravasaurs"] = "剑龙和暴掠龙",
		["Take a {object:176092} from the crate next to Derrington for {quest:5096}, done on the way back. Equip the {quest:5401}: Scourgestones only drop while you wear it."] = "从德灵顿旁边的箱子里拿一个{object:176092}，用于{quest:5096}，在回程时完成。装备{quest:5401}：只有佩戴它时才会掉落天灾石。",
		["Termite mounds"] = "白蚁丘",
		["Thaurissan dig site"] = "索瑞森挖掘场",
		["The Gorishi hive"] = "格里什虫巢",
		["The Lar'korwi Mates prowl the jungle north-west of {npc:9619}."] = "拉克维的配偶在{npc:9619}西北的丛林里潜行。",
		["The doll's head and its two sides lie in the houses around {npc:10926}; join them from your bags."] = "洋娃娃的脑袋和两半身体在{npc:10926}周围的房子里；在背包里把它们拼起来。",
		["The expedition's crate sits at an abandoned camp in the eastern jungle."] = "考察队的食物箱在东部丛林一个废弃的营地里。",
		["The expedition's lost equipment lies in the south-west jungle."] = "考察队丢失的研究设备在西南丛林里。",
		["The gorillas live on the north-east plateau. Stay out of the deepest cave: {npc:9622} lives there."] = "猩猩住在东北的高地上。别进入最深的洞穴：{npc:9622}住在那里。",
		["The next guide starts here, at the chapel's flight master."] = "下一个指南从这里的教堂飞行管理员处开始。",
		["The pylon stands on the slope east of the refuge."] = "水晶塔在避难所东边的山坡上。",
		["The raft lies on the shore of the south-eastern lake; the small pack sits in the water beside it."] = "破碎的木筏在东南湖泊的岸边；小背包就在旁边的水里。",
		["The silithid hive fills the south of the crater. Gorishi wasps and workers drop the scent gland; use the Scraping Vial on the egg mass inside the first chamber. The Hive Queen at the bottom is an elite boss: stay out of her chamber. {npc:9166} nest on the cliffs above the hive; their scales are for {npc:9998}."] = "异种蝎的巢穴占据着环形山南部。格里什异种蝎和格里什工蝎掉落格里什信息素；在第一个洞室里对卵块使用采集瓶。底部的格里什皇后是精英首领：别进入她的洞室。{npc:9166}在虫巢上方的悬崖上筑巢；它们的鳞片是给{npc:9998}的。",
		["The tar pits lie just south of the refuge. Tar Beasts, Lurkers and Creepers drop the {item:11834}."] = "焦油池就在避难所正南。焦油兽、焦油潜伏者和焦油爬行者掉落{item:11834}。",
		["The wooden sign beside {npc:9997}"] = "{npc:9997}旁边的木牌",
		["Use the Mangled Journal to start it"] = "使用被撕破的日记开始任务",
		["Western Pylon"] = "西部水晶塔",
		["Western jungle"] = "西部丛林",
		["{item:11116}, a rare drop"] = "{item:11116}，稀有掉落",
		["{npc:10302} sends you to {npc:9298} in {zone:1452}: keep it."] = "{npc:10302}让你去找{zone:1452}的{npc:9298}：留着它。",
		["{npc:10879}, the {object:36078}, beside the bat master"] = "{npc:10879}，在{object:36078}的蝙蝠管理员旁边",
		["{npc:6522}, the {object:36073}"] = "{npc:6522}，在{object:36073}",
		["{npc:8390}, the Apothecarium: the vials fill in {zone:1447} later"] = "{npc:8390}，在炼金房：瓶子之后在{zone:1447}装满",
		["{npc:9117}, at the back of the cave"] = "{npc:9117}，在洞穴深处",
		["{npc:9618}, just outside"] = "{npc:9618}，就在外面",
		["{npc:9619} camps in the south-east corner of the crater."] = "{npc:9619}在环形山的东南角扎营。",
		["{npc:9619} now asks for {npc:9622}'s pelt, back in the north-east cave: skip it."] = "{npc:9619}接下来要东北洞穴里{npc:9622}的毛皮：跳过它。",
		["{npc:9623} then wants a {item:10561}, an {skill:202} item. Skip it unless you have one."] = "{npc:9623}接着要一个{item:10561}，这是{skill:202}物品。除非你有，否则跳过。",
		["{npc:9623}, the robot on the plateau"] = "{npc:9623}，高地上的机器人",
		["{npc:9684}'s lair is just south of the pylon. Use {npc:9619}'s bait there; {npc:9684} is level 56 and hits hard, so start at full health."] = "{npc:9684}的巢穴就在水晶塔正南。在那里使用{npc:9619}的诱饵；{npc:9684}是56级，攻击很重，所以满血再开始。",
		["{npc:9998}, at the entrance"] = "{npc:9998}，在入口",
		["{npc:9998}, at the refuge entrance"] = "{npc:9998}，在避难所入口",
		["{npc:9999} sits on the ridge, lost and exhausted."] = "{npc:9999}坐在山脊上，迷路了，筋疲力尽。",
		["{quest:3822} walks the caves and mine tunnels of {quest:3821}; if he isn't home, clear the ogres around the entrances until he comes back."] = "{quest:3822}在{quest:3821}的洞穴和矿道里走动；如果他不在，就清理入口周围的食人魔，直到他回来。",
} end)()
t.guides["forever/horde/50-60/02-felwood"] = (function() return {
		["Derrington's watchtowers, Vandis' cauldron and {npc:11615}'s barrel are done on a later visit: keep them."] = "德灵顿的哨塔、范蒂丝的瘟疫之锅和{npc:11615}的木桶留到之后再来时完成：留着它们。",
		["Diseased Grizzlies"] = "生病的灰熊",
		["Diseased Wolves"] = "生病的狼",
		["East of Bloodvenom Post, the cratered vale where the Entropic Beasts and Horrors roam. Kill two of each, then walk to each of the three fel-water craters."] = "在血毒岗哨东边，是{npc:9878}和热能恐兽游荡的坑洼山谷。每种各杀两只，然后走到三个邪能水坑的每一个那里。",
		["Jadefire moonwell"] = "碧火月亮井",
		["Keep the branch: {npc:5770} is in {zone:1456}."] = "留着树枝：{npc:5770}在{zone:1456}。",
		["Keep {quest:5158}: {npc:5901} is in the {zone:1413}."] = "留着{quest:5158}：{npc:5901}在{zone:1413}。",
		["Keep {quest:8465} for {zone:1452}."] = "留着{quest:8465}去{zone:1452}。",
		["Northern crater"] = "北部水坑",
		["Only with 5 Deadwood Headdress Feathers"] = "仅当你有5根死木头饰羽毛时",
		["Radley and Durgen"] = "莱德雷和杜尔根",
		["Ride back south-east to the Sanctuary."] = "向东南骑回翡翠圣地。",
		["Ride north up the road again."] = "再次沿道路向北骑行。",
		["Ride north-west into Andorhal. {npc:10667} waits in the ruined inn on the west side of town; the skeletons inside are 54-57, so keep to the edges."] = "向西北骑进安多哈尔。{npc:10667}在城镇西侧被毁的旅店里等候；里面的骷髅是54-57级，所以沿着边缘走。",
		["Ride the road south through {zone:1448} to the Sanctuary."] = "沿道路向南穿过{zone:1448}前往翡翠圣地。",
		["Scarlet Crusade"] = "血色十字军",
		["Scarlet forward camp"] = "血色十字军前线营地",
		["Southern crater"] = "南部水坑",
		["Take the kitten to the same moonwell and release it there; once it has turned into a {npc:10042}, bring it back to {npc:9996} and click on it to hand it over."] = "把小猫带到同一口月亮井并在那里放出它；它变成{npc:10042}后，把它带回{npc:9996}那里，点击它交给她。",
		["The Annals lie among the Musty Tomes in Andorhal's town hall; open them until you find the right one."] = "达隆郡的历史就在安多哈尔市政厅里的发霉的书籍中间；一本本打开，直到找到正确的那本。",
		["The Deadwood furbolg village just west of the tunnel. {npc:9462} (56) stands among them. {npc:11557}, a friendly furbolg, sits at the north end of the village."] = "隧道正西的死木熊怪村庄。{npc:9462}（56级）站在它们中间。{npc:11557}是一个友善的熊怪，坐在村庄北端。",
		["The Jadefire moonwell"] = "碧火月亮井",
