		["Talk to {npc:252383}"] = "与{npc:252383}交谈",
		["Talk to {npc:252800}"] = "与{npc:252800}交谈",
		["Talk to {npc:253576}"] = "与{npc:253576}交谈",
		["Talk to {npc:254089}"] = "与{npc:254089}交谈",
