		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "这里的砂槌食人魔（45-48级）会掉落。也可以去拍卖行购买。",
		["Gnomeregan Exiles Reputation"] = "诺莫瑞根流亡者声望",
		["Keep handing in {quest:7812} until {faction:54} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "继续交还{quest:7812}，直到{faction:54}达到崇拜。{item:14047}：{zone:1423}的黑暗教徒和暗影法师（58-60级），或拍卖行。",
		["Keep handing in {quest:7812}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "继续交还{quest:7812}，每次20块{item:14047}。{item:14047}：{zone:1423}的黑暗教徒和暗影法师（58-60级），或拍卖行。",
		["Riverpaw Bandits and Taskmasters (level 16-18) drop it here. The Auction House works too."] = "这里的河爪强盗和河爪监工（16-18级）会掉落。也可以去拍卖行购买。",
		["Syndicate Mercenaries at Stromgarde (level 31-32) drop it here. The Auction House works too."] = "激流堡的辛迪加雇佣兵（31-32级）会掉落。也可以去拍卖行购买。",
		["{npc:14724} takes cloth for {faction:54} in {object:171524}, {zone:1455}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7812} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14724}在{zone:1455}的{object:171524}收取布料以提升{faction:54}声望。首次捐献毛料、丝绸、魔纹布和{item:14047}（各60块）只能做一次，每块布给的声望最多；之后{quest:7812}可重复做到崇拜。与其他种族的主城达到崇拜后，可购买该种族的坐骑。Forever的传承外交官特权可提高声望获取。",
		["{npc:14724}: {item:14047} delivered"] = "{npc:14724}：已交付{item:14047}",
		["{quest:7812} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7812}每次交还需要20块{item:14047}，可无限重复。按20的倍数带上{item:14047}，一次接一次全部交还。{item:14047}：{zone:1423}的黑暗教徒和暗影法师（58-60级），或拍卖行。",
		["{quest:7812} to Exalted"] = "{quest:7812}刷到崇拜",
		["{quest:7812} to Honored"] = "{quest:7812}刷到尊敬",
		["{quest:7812} to Revered"] = "{quest:7812}刷到崇敬",
} end)()
t.guides["forever/reputation/hydraxian-waterlords"] = (function() return {
		["Back to {npc:13278}"] = "回到{npc:13278}处",
		["Both elementals roam north-western {zone:1451}; the Rumblers cluster a little further north."] = "这两种元素都在{zone:1451}西北部游荡；沙漠奔行者聚集在稍北一些的地方。",
		["Dust Stormers and Desert Rumblers"] = "灰尘风暴和沙漠奔行者",
		["Hydraxian Waterlords Reputation"] = "海达希亚水元素声望",
		["Use the {item:17310} on the poisoned water elementals of {zone:1423}, then loot their {item:17309} (12)."] = "对{zone:1423}中被污染的水元素使用{item:17310}，然后拾取它们的{item:17309}（12个）。",
		["{faction:749} to Exalted"] = "{faction:749}刷到崇拜",
		["{faction:749} to Revered"] = "{faction:749}刷到崇敬",
		["{npc:13278} stands on a small island off the eastern coast of {zone:1447}; swim or walk the shallows out to him. The {faction:749} start out Neutral. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:13278}站在{zone:1447}东海岸外的一座小岛上；游过去或沿浅滩走过去。{faction:749}初始为中立。Forever的传承外交官特权可提高声望获取。",
		["{npc:9816} in Upper Blackrock Spire drops the {quest:6821}. This needs a raid group."] = "黑石塔上层的{npc:9816}掉落{quest:6821}。需要一支团队。",
} end)()
