		["Alternate Deadwood feathers ({npc:15395}) and Winterfall beads ({npc:11556}), whichever camp is less crowded."] = "轮流上交死木羽毛（{npc:15395}）和冬泉珠串（{npc:11556}），哪个营地人少就去哪个。",
		["Back to {npc:11554}"] = "回到{npc:11554}那里",
		["Back to {npc:11556}"] = "回到{npc:11556}那里",
		["Back to {npc:15395}"] = "回到{npc:15395}那里",
		["Deadwood furbolgs (level 48-50) camp at the southern end of {zone:1448}. Keep every {item:21377} they drop: {npc:11554} and {npc:15395} take them later."] = "死木熊怪（48-50级）在{zone:1448}南端扎营。保留它们掉落的每一根{item:21377}：{npc:11554}和{npc:15395}之后会收取。",
		["Feathers and beads to Friendly"] = "用羽毛和珠串刷到友善",
		["Feathers to Honored"] = "用羽毛刷到尊敬",
		["Go through {faction:576} to its {zone:1452} exit; {npc:11556} stands just outside. The quests and kills so far usually reach Unfriendly, and then the Timbermaw let you pass. If they still show red, kill more Deadwood by the tunnel first."] = "穿过{faction:576}到达通往{zone:1452}的出口；{npc:11556}就站在外面。到目前为止的任务和击杀通常能达到冷淡，然后木喉熊怪就会放你通过。如果它们仍显示红色，先在隧道旁多杀些死木熊怪。",
		["Keep turning in feathers and beads until Exalted."] = "继续上交羽毛和珠串，直到崇拜。",
		["The northern Deadwood (level 53-55) hold the camps just south of the tunnel. Keep their feathers too."] = "北部的死木熊怪（53-55级）占据着隧道南边不远处的营地。它们的羽毛也要保留。",
		["The northern Deadwood camps by the tunnel are the densest feather spot (35% drop chance there). Hand feathers to {npc:15395} at the tunnel, or to {npc:11554} in the south."] = "隧道旁的北部死木营地是羽毛最密集的地方（那里掉率35%）。把羽毛交给隧道口的{npc:15395}，或南边的{npc:11554}。",
		["Timbermaw Hold Reputation"] = "木喉要塞声望",
		["{faction:576} starts out Hostile, and its furbolgs in the tunnels attack until you reach Unfriendly. Every Deadwood and Winterfall furbolg you kill raises it, so the quests below pay twice. Forever's Legacy Diplomat perk increases reputation gains."] = "{faction:576}初始为敌对，隧道里的熊怪会攻击你，直到你达到冷淡。每杀一只死木和冬泉熊怪都会提升声望，所以下面的任务等于双倍回报。Forever的传承外交官特权可提高声望获取。",
		["{faction:576} to Exalted"] = "{faction:576}刷到崇拜",
		["{faction:576} to Revered"] = "{faction:576}刷到崇敬",
		["{npc:11556}: Beads for {npc:11556}"] = "{npc:11556}：给{npc:11556}的珠串",
		["{npc:15395} waits in northern {zone:1448} at the tunnel into {faction:576}."] = "{npc:15395}在{zone:1448}北部通往{faction:576}的隧道口等候。",
		["{npc:15395}: Feathers for {npc:15395}"] = "{npc:15395}：给{npc:15395}的羽毛",
} end)()
t.guides["forever/reputation/undercity"] = (function() return {
		["Dark Adepts and Shadowmages (level 58-60) drop it here; every Scourge kill here also counts toward the {object:92525} (see that guide). The Auction House works too."] = "这里的黑暗教徒和暗影法师（58-60级）会掉落；在这里击杀天灾军团也会提升{object:92525}声望（见该指南）。也可以去拍卖行购买。",
		["Dunemaul ogres (level 45-48) drop it here. The Auction House works too."] = "这里的砂槌食人魔（45-48级）会掉落。也可以去拍卖行购买。",
		["Keep handing in {quest:7819} until {faction:68} is Exalted. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "继续交还{quest:7819}，直到{faction:68}达到崇拜。{item:14047}：{zone:1423}的黑暗教徒和暗影法师（58-60级），或拍卖行。",
		["Keep handing in {quest:7819}, 20 {item:14047} at a time. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "继续交还{quest:7819}，每次20块{item:14047}。{item:14047}：{zone:1423}的黑暗教徒和暗影法师（58-60级），或拍卖行。",
		["Kolkar centaur (level 30-33) drop it here. The Auction House works too."] = "这里的科卡尔半人马（30-33级）会掉落。也可以去拍卖行购买。",
		["Undercity Reputation"] = "幽暗城声望",
		["{npc:14729} takes cloth for {faction:68} in {faction:68}. The first donations of Wool, Silk, Mageweave and {item:14047} (60 cloth each) are done once and give the most reputation per cloth; after them, {quest:7819} repeats until Exalted. Exalted with another race's city lets you buy that race's mounts. Forever's Legacy Diplomat perk increases reputation gains."] = "{npc:14729}在{faction:68}收取布料以提升{faction:68}声望。首次捐献毛料、丝绸、魔纹布和{item:14047}（各60块）只能做一次，每块布给的声望最多；之后{quest:7819}可重复做到崇拜。与其他种族的主城达到崇拜后，可购买该种族的坐骑。Forever的传承外交官特权可提高声望获取。",
		["{npc:14729}: {item:14047} delivered"] = "{npc:14729}：已交付{item:14047}",
		["{quest:7819} takes 20 {item:14047} per turn-in and repeats as often as you like. Bring {item:14047} in multiples of 20 and hand them all in at once, one turn-in after another. {item:14047}: Dark Adepts and Shadowmages (level 58-60) in {zone:1423}, or the Auction House."] = "{quest:7819}每次交还需要20块{item:14047}，可无限重复。按20的倍数带上{item:14047}，一次接一次全部交还。{item:14047}：{zone:1423}的黑暗教徒和暗影法师（58-60级），或拍卖行。",
		["{quest:7819} to Exalted"] = "{quest:7819}刷到崇拜",
		["{quest:7819} to Honored"] = "{quest:7819}刷到尊敬",
		["{quest:7819} to Revered"] = "{quest:7819}刷到崇敬",
} end)()
